(* [comment removed for export] *)
Definition fzB2_post (gp tp t0 t1 t2 s0 s1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6 : word) (F : bvmap 5 word) (fc : bv 32)
    (P allocb R : Z) (vs1 vs0 vra : word) (j7 j1 j4 : list byte) (m : mem) : machine_state -> Prop :=
  fun ms' => exists m' j8,
    ms' = MS (mkR (Z_to_bv 64 P_FZ_RET_CFG) (Z_to_bv 64 (P + -48)) gp tp t0 t1 t2 s0 s1
                  (Z_to_bv 64 R) (Z_to_bv 64 (P + -28)) a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
             F (Z_to_bv 64 P_MAKE_SVC_CONFIG) fc None m' (seg_rom usegs)
    /\ munch [(P + -28, P + -24); (P + 400, P + 408)]%Z m m' /\ wmono usegs m m' /\ mem_inv usegs m'
