(* [comment removed for export] *)
Definition fzB3_post (gp tp t0 t1 t2 s0 s1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6 : word) (F : bvmap 5 word) (fc : bv 32)
    (P allocb R : Z) (vs1 vs0 vra : word) (j7 j4 : list byte) (m : mem) : machine_state -> Prop :=
  fun ms' => exists m',
    ms' = MS (mkR (Z_to_bv 64 P_FZ_RET_SCH) (Z_to_bv 64 (P + -48)) gp tp t0 t1 t2 s0 s1
                  (Z_to_bv 64 R) (Z_to_bv 64 (P + -41)) a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
             F (Z_to_bv 64 P_MAKE_SVC_SCHED) fc None m' (seg_rom usegs)
    /\ munch [(P + -41, P + -40)]%Z m m' /\ wmono usegs m m' /\ mem_inv usegs m'
    /\ rw_cells usegs m' (P + -48) (IocFrame (CB 1 [b8 0]) (C8 (wz allocb)) (C4 (wz 4294967295)) vs1 vs0 vra j7 j4).

Lemma fzB3 : forall gp tp t0 t1 t2 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6
    (F : bvmap 5 word) fc (m : mem) (P allocb R : Z) (vs1 vs0 vra : word) (j7 j1 j4 j8 : list byte),
  rw_cells usegs m (P + -48) (IocFrame (CB 1 j1) (C8 (wz allocb)) (C4 (wz 4294967295)) vs1 vs0 vra j7 j4) ->
  rw_cells usegs m (P + 392) [C8 (wz allocb); C8 (wz R); CB 8 j8] ->
  hceil <= P + -48 -> P + 512 < 2^64 ->
  0 < R -> R mod 8 = 0 -> R < 2^64 ->                                                  (* [comment removed for export] *)
  mem_inv usegs m ->
  evt usegs (fzB3_post gp tp t0 t1 t2 (Z_to_bv 64 (P + 392)) s1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6 F fc P allocb R vs1 vs0 vra j7 j4 m)
    (MS (mkR (Z_to_bv 64 P_FZ_RET_CFG) (Z_to_bv 64 (P + -48)) gp tp t0 t1 t2 (Z_to_bv 64 (P + 392)) s1 a0 a1 a2 a3 a4 a5 a6 a7
             s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
