Definition fzB4_post (gp tp t0 t1 t2 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6 : word) (F : bvmap 5 word) (fc : bv 32)
    (P D N allocb R S lo : Z) (m : mem) : machine_state -> Prop :=
  fun ms' => exists m',
    ms' = MS (mkR (Z_to_bv 64 P_FZ_RET_SCT) (Z_to_bv 64 P) gp tp t0 t1 t2 (Z_to_bv 64 N) (Z_to_bv 64 D)
                  (Z_to_bv 64 (P + 360)) (Z_to_bv 64 (P + 392)) (Z_to_bv 64 D) (Z_to_bv 64 N) a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
             F (Z_to_bv 64 P_STREAM_CTOR) fc None m' (seg_rom usegs)
    /\ munch [(P + 408, P + 416)]%Z m m' /\ wmono usegs m m' /\ mem_inv usegs m'
    /\ rw_cells usegs m' (P + 392) (IoCtxCells allocb R S)
    /\ stk usegs m' lo P.

Lemma fzB4 : forall gp tp t0 t1 t2 s1 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6
    (F : bvmap 5 word) fc (m : mem) (P D N allocb R S lo : Z) (j7 j4 j8 : list byte),
  rw_cells usegs m (P + -48) (IocFrame (CB 1 [b8 0]) (C8 (wz allocb)) (C4 (wz 4294967295)) (Z_to_bv 64 D) (Z_to_bv 64 N) (Z_to_bv 64 P_FZ_RET_IOC) j7 j4) ->
  rw_cells usegs m (P + 392) [C8 (wz allocb); C8 (wz R); CB 8 j8] ->
