  mem_inv usegs m ->
  evt usegs (fzB4_post gp tp t0 t1 t2 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6 F fc P D N allocb R S lo m)
